import * as T from '../lib/three/build/three.module.js';
import {mergeGeometries} from '../lib/three/examples/jsm/utils/BufferGeometryUtils.js';
import {FLIGHT} from './config.js';
const color={body:0x192632,edge:0x374654,black:0x080f18,trim:0xa98560,orange:0xe4a468,white:0xc8d6df};
const materials=new Map();
const mat=(c,roughness=.65,metalness=.35)=>{const key=[c,roughness,metalness].join(':');if(!materials.has(key))materials.set(key,new T.MeshStandardMaterial({color:c,roughness,metalness}));return materials.get(key);};
function box(parent,w,h,d,m,x,y,z){const mesh=new T.Mesh(new T.BoxGeometry(w,h,d),m);mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
function cylinderBetween(parent,a,b,r,m){const va=new T.Vector3(...a),vb=new T.Vector3(...b);const d=vb.clone().sub(va);const mesh=new T.Mesh(new T.CylinderGeometry(r,r,d.length(),8),m);mesh.position.copy(va).add(vb).multiplyScalar(.5);mesh.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());parent.add(mesh);return mesh;}
function textTexture(text,width=512,height=128,background='#121d28',ink='#9aaebb'){
  const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;
  const ctx=canvas.getContext('2d');ctx.fillStyle=background;ctx.fillRect(0,0,width,height);ctx.fillStyle=ink;ctx.textAlign='center';ctx.font=`${height*.30}px monospace`;ctx.fillText(text,width/2,height*.62);
  const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;return texture;
}
function label(parent,text,x,y,z,w=.16,h=.035){const mesh=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:textTexture(text),transparent:false}));mesh.position.set(x,y,z);parent.add(mesh);return mesh;}
function screen(parent,x,y,z,w,h){
  const g=new T.Group();g.position.set(x,y,z);g.rotation.x=-.17;parent.add(g);
  box(g,w+.038,h+.038,.032,mat(0x070c12),0,0,0);
  box(g,w+.055,.008,.035,mat(color.edge),0,-h/2-.027,0);
  const canvas=document.createElement('canvas');canvas.width=768;canvas.height=384;const ctx=canvas.getContext('2d');
  const texture=new T.CanvasTexture(canvas);texture.colorSpace=T.SRGBColorSpace;
  const plane=new T.Mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:texture}));plane.position.z=.018;g.add(plane);
  for(const dx of [-1,1])for(const dy of [-1,1]){const bolt=new T.Mesh(new T.CylinderGeometry(.004,.004,.002,6),mat(color.edge));bolt.rotation.x=Math.PI/2;bolt.position.set(dx*(w/2+.011),dy*(h/2+.011),.019);g.add(bolt);}
  return {ctx,texture};
}
export function createCockpit(){
  const root=new T.Group();root.name='STATIC_SEATED_COCKPIT';
  const body=mat(color.body),edge=mat(color.edge,.45,.65),black=mat(color.black),trim=mat(color.trim,.42,.7);
  const glow=new T.MeshBasicMaterial({color:color.orange});const paleGlow=new T.MeshBasicMaterial({color:0x739db0});
  // Enclosed lower fuselage and the canopy's permanent visual anchors.
  box(root,2.16,.15,2.9,black,0,.03,-.35);
  box(root,.22,.72,2.5,body,-1.05,.37,-.36);box(root,.22,.72,2.5,body,1.05,.37,-.36);
  box(root,2.2,1.15,.2,body,0,.58,.94);
  box(root,1.94,.15,.15,edge,0,.93,-1.2);
  for(const side of [-1,1]){
    // Broad diagonal canopy spars frame the view but leave the center open.
    cylinderBetween(root,[side*.85,.77,-.93],[side*1.05,1.92,-1.18],.042,edge);
    cylinderBetween(root,[side*1.05,1.92,-1.18],[side*.62,2.10,-1.02],.044,body);
    cylinderBetween(root,[side*.62,2.10,-1.02],[side*.66,2.12,.65],.052,body);
    cylinderBetween(root,[side*.66,2.12,.65],[side*1.02,.58,.75],.065,body);
    cylinderBetween(root,[side*.99,.73,-1.15],[side*.99,.73,.72],.048,edge);
    cylinderBetween(root,[side*.85,.82,-.95],[side*1.04,1.92,-1.18],.008,trim);
    box(root,.24,.18,.73,body,side*.64,.60,-.3);
    box(root,.25,.014,.75,edge,side*.64,.70,-.3);
    box(root,.008,.009,.54,glow,side*.76,.714,-.3);
    // Braces, inset panel ribs and reachable elbow rests.
    box(root,.25,.09,.42,black,side*.64,.71,.27);
    for(let j=0;j<7;j++)box(root,.13,.008,.009,edge,side*.64,.722,.14+j*.04);
    for(let j=0;j<5;j++)box(root,.035,.20,.08,edge,side*.92,.45,-.95+j*.40);
  }
  cylinderBetween(root,[-.62,2.10,-1.02],[.62,2.10,-1.02],.045,edge);
  const glass=new T.Mesh(new T.PlaneGeometry(1.95,1.1),new T.MeshBasicMaterial({color:0x76a8bf,transparent:true,opacity:.018,depthWrite:false,side:T.DoubleSide}));glass.position.set(0,1.52,-1.23);root.add(glass);
  // Dashboard slab, sloped front and amber instrument lip.
  const dash=box(root,1.83,.25,.34,body,0,.74,-.96);dash.rotation.x=-.11;
  box(root,1.78,.024,.12,black,0,.90,-1.02);
  box(root,1.72,.008,.012,glow,0,.918,-.95);
  for(const s of [-1,1]){const p=box(root,.29,.30,.30,body,s*.77,.72,-.83);p.rotation.z=-s*.15;}
  const left=screen(root,-.55,.82,-.754,.32,.19);
  const center=screen(root,0,.815,-.747,.61,.24);
  const right=screen(root,.55,.82,-.754,.32,.19);
  // Genuine pivots: controller grip moves the handles rather than pointing at a UI.
  const throttle=new T.Group();throttle.position.set(-.43,.68,-.36);root.add(throttle);
  box(throttle,.18,.034,.31,black,0,-.014,0);
  for(let j=0;j<9;j++)box(throttle,.024,.002,.004,trim,.065,.006,-.12+j*.03);
  label(throttle,'THRUST',0,.021,.17,.17,.035).rotation.x=-Math.PI/2;
  const throttlePivot=new T.Group();throttle.add(throttlePivot);
  cylinderBetween(throttlePivot,[0,0,0],[0,.21,0],.014,edge);
  const throttleHandle=box(throttlePivot,.14,.058,.068,black,0,.21,0);
  box(throttlePivot,.14,.008,.071,trim,0,.244,0);
  box(throttlePivot,.06,.006,.073,glow,0,.249,0);
  const stick=new T.Group();stick.position.set(.39,.68,-.37);root.add(stick);
  const boot=new T.Mesh(new T.CylinderGeometry(.048,.085,.075,12),black);boot.position.y=.02;stick.add(boot);
  const stickPivot=new T.Group();stick.add(stickPivot);
  cylinderBetween(stickPivot,[0,.02,0],[0,.23,0],.018,edge);
  const stickHandle=box(stickPivot,.07,.105,.07,black,0,.235,0);
  box(stickPivot,.055,.025,.018,trim,0,.28,-.04);
  box(stickPivot,.02,.012,.012,glow,0,.29,-.051);
  for(let j=0;j<4;j++)box(stickPivot,.072,.005,.073,edge,0,.20+j*.018,0);
  // Three physical toggle switches on the near console, reachable from the seat.
  const switches=[];
  const switchPanel=new T.Group();switchPanel.position.set(0,.64,-.53);switchPanel.rotation.x=-.55;root.add(switchPanel);
  box(switchPanel,.49,.12,.03,black,0,0,0);
  ['REACTOR','CANNON','LIGHTS'].forEach((name,i)=>{
    const pivot=new T.Group();pivot.position.set((i-1)*.16,0,.025);switchPanel.add(pivot);
    const washer=new T.Mesh(new T.CylinderGeometry(.022,.022,.007,12),edge);washer.rotation.x=Math.PI/2;pivot.add(washer);
    const arm=new T.Group();pivot.add(arm);
    cylinderBetween(arm,[0,0,0],[0,.038,.032],.006,trim);
    const cap=new T.Mesh(new T.SphereGeometry(.011,8,6),new T.MeshBasicMaterial({color:0x9bd3b2}));cap.position.set(0,.038,.032);arm.add(cap);
    label(switchPanel,name,(i-1)*.16,-.041,.023,.13,.022);
    switches.push({pivot,arm,cap});
  });
  // Cockpit plaque, caution strips, side indicators and hardware add scale.
  label(root,'A P H E L I O N',0,.989,-1.12,.29,.032);
  label(root,'GRIP HANDLES  /  TRIGGER FIRE',0,1.045,-1.17,.48,.025);
  label(root,'A-07 / PATHFINDER',-.73,.97,-1.1,.25,.027);
  label(root,'NO STEP',.77,.97,-1.1,.11,.025);
  for(let s=-1;s<=1;s+=2){for(let j=0;j<5;j++){const led=box(root,.025,.009,.005,j<4?paleGlow:glow,s*(.72-j*.025),.925,-.94);}
    for(let j=0;j<4;j++)box(root,.045,.015,.006,edge,s*.79,.81-j*.028,-.658);
    const dial=new T.Mesh(new T.CylinderGeometry(.027,.027,.025,16),edge);dial.rotation.x=Math.PI/2;dial.position.set(s*.78,.68,-.64);root.add(dial);
    box(root,.004,.027,.003,trim,s*.78,.68,-.624);
  }
  const chair=box(root,.53,.10,.49,black,0,.38,.37);box(root,.53,.6,.1,black,0,.73,.64);
  const cabinLight=new T.PointLight(0x92bfd8,1.8,3,2);cabinLight.position.set(0,1.4,.1);root.add(cabinLight);
  const consoleLight=new T.PointLight(0xffba79,.7,2,2);consoleLight.position.set(0,1.01,-.68);root.add(consoleLight);
  const halo=new T.Mesh(new T.RingGeometry(.013,.019,24),glow);halo.position.set(0,1.25,-1.80);halo.material.transparent=true;halo.material.opacity=.5;root.add(halo);
  const hud=new T.Group();hud.position.set(0,1.25,-1.8);root.add(hud);
  for(let s=-1;s<=1;s+=2){box(hud,.055,.002,.002,paleGlow,s*.045,0,0);box(hud,.002,.035,.002,paleGlow,0,s*.033,0);}
  const vignetteMaterial=new T.ShaderMaterial({transparent:true,depthTest:false,depthWrite:false,side:T.DoubleSide,uniforms:{strength:{value:0}},vertexShader:'varying vec2 vUv; void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 vUv;uniform float strength;void main(){float r=length((vUv-.5)*2.);float edge=mix(1.48,.34,strength);float a=smoothstep(edge,edge+.38,r)*strength*.94;gl_FragColor=vec4(.012,.021,.035,a);}' });
  const vignette=new T.Mesh(new T.PlaneGeometry(2.6,2.6),vignetteMaterial);vignette.position.z=-.53;vignette.renderOrder=999;
  const displayBase=(ctx,title)=>{ctx.fillStyle='#09151f';ctx.fillRect(0,0,768,384);ctx.strokeStyle='#315364';ctx.lineWidth=2;ctx.strokeRect(8,8,752,368);ctx.fillStyle='#83a2b5';ctx.font='21px monospace';ctx.textAlign='left';ctx.fillText(title,30,44);ctx.fillStyle='#4b707c';ctx.fillRect(30,61,708,1);};
  function update(flight,time){
    throttlePivot.rotation.x=(.5-flight.throttle)*2*FLIGHT.throttleAngle;
    stickPivot.rotation.x=flight.stick.y*FLIGHT.stickAngle;stickPivot.rotation.z=-flight.stick.x*FLIGHT.stickAngle;
    switches.forEach((s,i)=>{s.arm.rotation.x=flight.switches[i]?0:1.5;s.cap.material.color.setHex(flight.switches[i]?0x9bd3b2:0xc16a4c);});
    cabinLight.intensity=flight.switches[2]?1.8:.18;
    vignetteMaterial.uniforms.strength.value=flight.vignette;
    if(time-update.last<.10)return;update.last=time;
    let c=left.ctx;displayBase(c,'01 / VELOCITY');c.fillStyle='#c4e4e6';c.font='108px monospace';c.fillText(flight.speed.toFixed(1).padStart(4,'0'),30,195);c.font='25px monospace';c.fillStyle='#628c9e';c.fillText('m/s   ·   INERTIAL',34,241);c.fillStyle='#40535e';c.fillRect(34,279,690,20);c.fillStyle='#c7a17a';c.fillRect(34,279,690*flight.throttle,20);c.font='22px monospace';c.fillText(`THRUST  ${Math.round(flight.throttle*100)}%`,34,345);left.texture.needsUpdate=true;
    c=right.ctx;displayBase(c,'03 / HULL INTEGRITY');c.fillStyle=flight.hull>30?'#b3d8c6':'#ed8d68';c.font='112px monospace';c.fillText(String(Math.ceil(flight.hull)).padStart(3,'0'),30,197);c.font='32px monospace';c.fillText('%',265,197);c.font='23px monospace';c.fillStyle='#6b8f9b';c.fillText(flight.dead?'CRITICAL / TRIGGER RESET':flight.kills>=FLIGHT.goal?'CONTRACT COMPLETE':'STRUCTURE NOMINAL',30,249);for(let i=0;i<10;i++){c.fillStyle=i<flight.hull/10?'#8eb7a6':'#223543';c.fillRect(32+i*70,280,55,19);}c.fillStyle='#86a6b3';c.font='21px monospace';c.fillText(`TARGETS   ${String(flight.kills).padStart(2,'0')} / 12`,32,345);right.texture.needsUpdate=true;
    c=center.ctx;displayBase(c,'02 / PROXIMITY SCAN');const cx=384,cy=216;c.strokeStyle='#304f5b';for(let r=40;r<=145;r+=45){c.beginPath();c.ellipse(cx,cy,r*1.5,r*.75,0,0,Math.PI*2);c.stroke();}c.beginPath();c.moveTo(145,cy);c.lineTo(623,cy);c.moveTo(cx,90);c.lineTo(cx,339);c.stroke();
    c.fillStyle='#d4ad7f';for(let i=0;i<13;i++){const a=i*2.39;const r=45+(i*29%160);const x=cx+Math.sin(a)*r;const y=cy+Math.cos(a)*r*.49;c.fillRect(x-3,y-3,6,6);}c.strokeStyle='#b8d8d3';c.beginPath();c.moveTo(cx,cy-14);c.lineTo(cx-9,cy+9);c.lineTo(cx,cy+5);c.lineTo(cx+9,cy+9);c.closePath();c.stroke();c.fillStyle='#6895a6';c.font='18px monospace';c.fillText('ASTERION / SECTOR 07',30,350);c.textAlign='right';c.fillText(`${flight.acceleration.toFixed(1)} m/s²`,733,350);center.texture.needsUpdate=true;
  }update.last=-1;
  function controlPoint(kind,target=new T.Vector3()){
    root.updateMatrixWorld(true);
    if(kind==='throttle')return throttlePivot.localToWorld(target.set(0,.21,0));
    if(kind==='stick')return stickPivot.localToWorld(target.set(0,.235,0));
    return switches[kind].cap.getWorldPosition(target);
  }
  // Bake fixed hardware by material. Pivots and their descendants stay separate.
  root.updateMatrixWorld(true);
  const moving=new Set([throttlePivot,stickPivot,...switches.map(s=>s.arm)]),batches=new Map();
  root.traverse(object=>{
    if(!object.isMesh||Array.isArray(object.material))return;
    for(let p=object;p&&p!==root;p=p.parent)if(moving.has(p))return;
    const list=batches.get(object.material)||[];list.push(object);batches.set(object.material,list);
  });
  for(const [material,meshes] of batches){
    if(meshes.length<2)continue;
    const geometry=mergeGeometries(meshes.map(m=>m.geometry.clone().applyMatrix4(m.matrixWorld)),false);
    if(!geometry)continue;
    meshes.forEach(m=>m.removeFromParent());root.add(new T.Mesh(geometry,material));
  }
  return {root,throttle,throttlePivot,throttleHandle,stick,stickPivot,stickHandle,switches,vignette,cabinLight,update,controlPoint};
}

export const XR_CONFIG = Object.freeze({mode:'immersive-vr', requiredFeatures:['local'], optionalFeatures:[]});
export const FLIGHT = Object.freeze({maxThrust:10, vignetteThreshold:2.5, snapAngle:Math.PI/12, stickAngle:0.38, throttleAngle:0.65, goal:12});
export const clamp = (v,lo,hi) => Math.max(lo,Math.min(hi,v));

import * as THREE from '../lib/three/build/three.module.js';
import {FLIGHT,clamp} from './config.js';
const forward = new THREE.Vector3(0,0,-1);
const axisX = new THREE.Vector3(1,0,0), axisY = new THREE.Vector3(0,1,0);
const change = new THREE.Quaternion();
export class Flight {
  constructor(){this.reset();}
  reset(){
    this.position = new THREE.Vector3(); this.velocity = new THREE.Vector3(); this.orientation = new THREE.Quaternion();
    this.throttle=0; this.stick={x:0,y:0}; this.hull=100; this.kills=0; this.acceleration=0; this.elapsed=0;
    this.switches=[true,true,true]; this.dead=false; this.damageCooldown=0; this.fireCooldown=0; this.vignette=0;
  }
  get speed(){return this.velocity.length();}
  update(dt){
    this.elapsed+=dt;this.damageCooldown=Math.max(0,this.damageCooldown-dt);this.fireCooldown=Math.max(0,this.fireCooldown-dt);
    if(this.dead){this.acceleration=0;this.throttle=0;this.vignette*=Math.exp(-dt*6);return;}
    // Body steering is commanded by the stick. Nothing turns without pilot input.
    change.setFromAxisAngle(axisY,-this.stick.x*0.42*dt);this.orientation.multiply(change);
    change.setFromAxisAngle(axisX,this.stick.y*0.34*dt);this.orientation.multiply(change);this.orientation.normalize();
    this.acceleration=this.switches[0]?clamp(this.throttle,0,1)*FLIGHT.maxThrust:0;
    // Semi-implicit Newtonian integration; intentionally no velocity damping or speed cap.
    this.velocity.addScaledVector(forward.clone().applyQuaternion(this.orientation),this.acceleration*dt);
    this.position.addScaledVector(this.velocity,dt);
    const target=clamp((this.acceleration-FLIGHT.vignetteThreshold)/7.5,0,1);
    this.vignette += (target-this.vignette)*(1-Math.exp(-dt*6));
  }
  snap(direction){if(!this.dead)this.orientation.multiply(change.setFromAxisAngle(axisY,-direction*FLIGHT.snapAngle));}
  damage(amount){
    if(this.dead||this.damageCooldown>0)return false;
    this.hull=Math.max(0,this.hull-amount);this.damageCooldown=1.2;
    if(this.hull===0){this.dead=true;this.throttle=0;this.acceleration=0;this.velocity.set(0,0,0);}
    return true;
  }
  canFire(){return !this.dead&&this.switches[0]&&this.switches[1]&&this.fireCooldown===0;}
}

import * as T from '../lib/three/build/three.module.js';
import {FLIGHT,clamp} from './config.js';
const pos=new T.Vector3(),local=new T.Vector3();
export class Input {
  constructor({renderer,scene,camera,cockpit,flight,onFire,onToggle,onRecenter,onRestart,audio}){
    Object.assign(this,{renderer,scene,camera,cockpit,flight,onFire,onToggle,onRecenter,onRestart,audio});
    this.keys=new Set();this.controllers=[];this.look={yaw:0,pitch:-.12};this.dragging=false;this.lastPointer={x:0,y:0};
    const canvas=renderer.domElement;
    window.addEventListener('keydown',e=>{
      if(document.querySelector('dialog[open]'))return;
      if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();
      this.audio.unlock();this.keys.add(e.code);
      if(e.repeat)return;
      if(e.code==='KeyQ')flight.snap(-1);if(e.code==='KeyE')flight.snap(1);
      if(['Digit1','Digit2','Digit3'].includes(e.code))onToggle(Number(e.code.slice(-1))-1);
      if(e.code==='KeyR')onRecenter();if(e.code==='KeyX')flight.throttle=0;
    });
    window.addEventListener('keyup',e=>this.keys.delete(e.code));
    window.addEventListener('blur',()=>{this.keys.clear();this.releaseAll();this.dragging=false;});
    canvas.addEventListener('pointerdown',e=>{if(renderer.xr.isPresenting)return;this.audio.unlock();this.dragging=true;this.lastPointer={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});
    canvas.addEventListener('pointermove',e=>{if(!this.dragging||renderer.xr.isPresenting)return;this.look.yaw=clamp(this.look.yaw-(e.clientX-this.lastPointer.x)*.003,-.9,.9);this.look.pitch=clamp(this.look.pitch-(e.clientY-this.lastPointer.y)*.003,-.60,.52);this.lastPointer={x:e.clientX,y:e.clientY};});
    canvas.addEventListener('pointerup',()=>this.dragging=false);canvas.addEventListener('pointercancel',()=>this.dragging=false);
    for(let i=0;i<2;i++){
      const grip=renderer.xr.getControllerGrip(i),target=renderer.xr.getController(i);scene.add(grip,target);
      const model=new T.Group();
      const handle=new T.Mesh(new T.CylinderGeometry(.018,.023,.11,8),new T.MeshStandardMaterial({color:0x647987,metalness:.5,roughness:.5}));handle.rotation.x=.25;handle.position.y=-.04;model.add(handle);
      const rim=new T.Mesh(new T.TorusGeometry(.035,.004,5,20),new T.MeshBasicMaterial({color:0xe3b27d}));rim.rotation.x=-.45;rim.position.set(0,.025,-.015);model.add(rim);
      const dot=new T.Mesh(new T.SphereGeometry(.008,8,6),new T.MeshBasicMaterial({color:0x9ed3c3}));model.add(dot);grip.add(model);model.visible=false;
      const state={grip,target,model,source:null,grab:null,offset:{},firing:false,snapReady:true,recenterHeld:false,hover:null};this.controllers.push(state);
      target.addEventListener('connected',e=>{state.source=e.data;model.visible=e.data.targetRayMode==='tracked-pointer';});
      target.addEventListener('disconnected',()=>{this.release(state);state.source=null;state.model.visible=false;});
      target.addEventListener('squeezestart',()=>this.grab(state));target.addEventListener('squeezeend',()=>this.release(state));
      target.addEventListener('selectstart',()=>{
        audio.unlock();if(flight.dead){onRestart();return;}grip.getWorldPosition(pos);let found=-1,dist=.145;
        for(let j=0;j<3;j++){const d=pos.distanceTo(cockpit.controlPoint(j));if(d<dist){dist=d;found=j;}}
        if(found>=0){onToggle(found);this.pulse(state,.25,40);state.firing=false;}else if(state.source?.handedness!=='left'){state.firing=true;}
      });
      target.addEventListener('selectend',()=>state.firing=false);
    }
  }
  pulse(state,strength=.3,duration=40){const gp=state.source?.gamepad;try{const a=gp?.hapticActuators?.[0];if(a?.pulse)a.pulse(strength,duration).catch(()=>{});else gp?.vibrationActuator?.playEffect?.('dual-rumble',{duration,strongMagnitude:strength,weakMagnitude:strength}).catch(()=>{});}catch{}}
  haptic(strength,duration){this.controllers.forEach(s=>this.pulse(s,strength,duration));}
  nearest(state){
    state.grip.getWorldPosition(pos);let result=null,distance=.17;
    for(const kind of ['throttle','stick']){
      if(this.controllers.some(c=>c!==state&&c.grab===kind))continue;
      const d=pos.distanceTo(this.cockpit.controlPoint(kind));if(d<distance){distance=d;result=kind;}
    }return result;
  }
  grab(state){
    const kind=this.nearest(state);if(!kind)return;state.grab=kind;
    state.grip.getWorldPosition(local);this.cockpit[kind].worldToLocal(local);
    if(kind==='throttle')state.offset.angle=this.cockpit.throttlePivot.rotation.x-Math.atan2(local.z,local.y);
    else{state.offset.x=this.flight.stick.x-Math.atan2(local.x,local.y)/FLIGHT.stickAngle;state.offset.y=this.flight.stick.y-Math.atan2(local.z,local.y)/FLIGHT.stickAngle;}
    this.pulse(state,.35,45);
  }
